def frontier_line(grid, line_color):
    """Shift the shape flush against the full one-color line (frontier), then draw a full-length line of line_color just beyond it on the far side."""
    from collections import Counter
    H, W = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    full_rows = [i for i in range(H) if len(set(grid[i])) == 1 and grid[i][0] != bg]
    full_cols = [j for j in range(W) if len({grid[i][j] for i in range(H)}) == 1 and grid[0][j] != bg]
    cells = lambda g: [(i, j) for i in range(H) for j in range(W) if g[i][j] not in (bg,)]
    shape = next(c for c in counts if c not in (bg, grid[full_rows[0]][0] if full_rows else grid[0][full_cols[0]]))
    out = [row[:] for row in grid]
    if full_rows:
        fr = full_rows[0]
        rows = {i for i in range(H) if shape in grid[i]}
        if min(rows) != fr + 1:
            step = fr + 1 - min(rows)
            for i, j in [(i, j) for i in rows for j in range(W) if out[i][j] == shape]:
                out[i][j] = bg
            for i, j in [(i, j) for i in rows for j in range(W) if grid[i][j] == shape]:
                out[i + step][j] = shape
        newrows = {i for i in range(H) if shape in out[i]}
        out[max(newrows) + 1] = [line_color] * W
    else:
        fc = full_cols[0]
        cols = {j for j in range(W) if any(grid[i][j] == shape for i in range(H))}
        if min(cols) != fc + 1:
            step = fc + 1 - min(cols)
            for i in range(H):
                for j in cols:
                    if grid[i][j] == shape: out[i][j] = bg
            for i in range(H):
                for j in cols:
                    if grid[i][j] == shape: out[i][j + step] = shape
        newcols = {j for j in range(W) if any(out[i][j] == shape for i in range(H))}
        c = max(newcols) + 1
        for i in range(H): out[i][c] = line_color
    return out
